mapper.select:
SELECT
saa.user_allocation_id
FROM
sys_appoint_approver saa


        and saa.process_instance_id = #{processInstanceId}


        and saa.sid_code = #{sidCode}

SELECT saa.approver_id, saa.user_id, saa.process_instance_id, saa.user_allocation_id, saa.source_id, saa.source_table, saa.sid_code, ( SELECT fee. NAME FROM fnd_employee_assigns fea, fnd_employee fee, fnd_org_unit fn, fnd_org_position fop, fnd_company fc, sys_user_allocation sua WHERE fea.employee_id = fee.employee_id AND fn.unit_id = fea.unit_id AND fop.position_id = fea.position_id AND fc.company_id = fea.company_id AND sua.employee_assign_id = fea.employee_assign_id AND sua.allocation_id IS NOT NULL AND SUA.allocation_id = saa.user_allocation_id ) user_allocation_id_n, ( SELECT fop.position_name FROM fnd_employee_assigns fea, fnd_employee fee, fnd_org_unit fn, fnd_org_position fop, fnd_company fc, sys_user_allocation sua WHERE fea.employee_id = fee.employee_id AND fn.unit_id = fea.unit_id AND fop.position_id = fea.position_id AND fc.company_id = fea.company_id AND sua.employee_assign_id = fea.employee_assign_id AND sua.allocation_id IS NOT NULL AND SUA.allocation_id = saa.user_allocation_id ) position_name, ( SELECT fc.company_short_name FROM fnd_employee_assigns fea, fnd_employee fee, fnd_org_unit fn, fnd_org_position fop, fnd_company fc, sys_user_allocation sua WHERE fea.employee_id = fee.employee_id AND fn.unit_id = fea.unit_id AND fop.position_id = fea.position_id AND fc.company_id = fea.company_id AND sua.employee_assign_id = fea.employee_assign_id AND sua.allocation_id IS NOT NULL AND SUA.allocation_id = saa.user_allocation_id ) company_short_name FROM sys_appoint_approver saa
and saa.process_instance_id = #{processInstanceId}
and saa.sid_code = #{sidCode}

select t.user_allocation_id from sys_appoint_approver t where t.approver_id = ( SELECT max(saa.approver_id) FROM sys_appoint_approver saa
and saa.source_id = #{sourceId}
and upper(saa.source_table) = #{sourceTable}
)

select
t.user_allocation_id
from sys_appoint_approver t
where t.approver_id = (
SELECT
max(saa.approver_id)
FROM
sys_appoint_approver saa


        and saa.source_id = #{sourceId}


        and upper(saa.source_table) = #{sourceTable}


        and saa.sid_code = #{sidCode}


)
